def match_invoice(invoice_data, transaction_data):
    """
    Matches an invoice against a list of transactions.
    """
    logger.info(f"Attempting to match invoice {invoice_data.get('id')}")

    for tx in transaction_data:
        if tx['amount'] == invoice_data['amount'] and tx['date'] == invoice_data['date']:
            return tx

    return None

