import re

def normalize_invoice_number(invoice_no):
    """Removes non-alphanumeric characters and leading zeros."""
    if not invoice_no:
        return ""
    return re.sub(r'[^A-Z0-9]', '', str(invoice_no).upper()).lstrip('0')

def calculate_tax(amount, rate=0.2):
    """Simple tax calculation."""
    return round(amount * rate, 2)

def validate_currency(currency_code):
    """Checks if the currency code is a valid 3-letter ISO code."""
    return bool(re.match(r'^[A-Z]{3}$', str(currency_code).upper()))

