import logging

logger = logging.getLogger(__name__)

def match_invoice_to_payment(invoice_id, payment_data):
    """
    Matches an invoice ID against a list of payment records.
    Returns the matching payment record or None.
    """
    logger.info(f"Attempting to match invoice {invoice_id}")
    for payment in payment_data:
        if payment.get('reference') == invoice_id:
            logger.info(f"Match found: {payment['id']}")
            return payment
    return None

def process_batch(invoices, payments):
    results = []
    for inv in invoices:
        match = match_invoice_to_payment(inv['id'], payments)
        results.append({
            'invoice_id': inv['id'],
            'matched': match is not None,
            'payment_id': match['id'] if match else None
        })
    return results

