def create_vault_paths(service_name, environments):
    vault_url = os.getenv("VAULT_ADDR", "https://vault.acme.local:8200")
    vault_token = os.getenv("VAULT_TOKEN")

    if not vault_token:
        print("Error: VAULT_TOKEN not set.")
        sys.exit(1)

    client = hvac.Client(url=vault_url, token=vault_token)

    for env in environments:
        path = f"{env}/k8s/{service_name}"
        mount_point = "secret"

        print(f"Provisioning Vault path: {mount_point}/{path}")
        try:
            client.secrets.kv.v2.create_or_update_secret(
                mount_point=mount_point,
                path=path,
                secret={'status': 'provisioned'}
            )
        except Exception as e:
            print(f"Failed to create path {path}: {e}")
            sys.exit(1)

if __name__ == "__main__":
    if len(sys.argv) < 3:
        print("Usage: setup_vault.py <service_name> <env1,env2,...>")
        sys.exit(1)

    svc = sys.argv[1]
    envs = sys.argv[2].split(',')
