import { NextRequest, NextResponse } from 'next/server';
import { UAParser } from 'ua-parser-js';

const SUPPORTED_SAFARI_VERSION = 17;

export function middleware(req: NextRequest) {
  const { pathname } = req.nextUrl;

  // Avoid redirect loops
  if (pathname.startsWith('/supported-browsers') || pathname.startsWith('/_next')) {
    return NextResponse.next();
  }

  const uaString = req.headers.get('user-agent') || '';
  const parser = new UAParser(uaString);
  const browser = parser.getBrowser();

  if (browser.name === 'Safari' || browser.name === 'Mobile Safari') {
    const majorVersion = parseInt(browser.major || '0', 10);
    if (majorVersion < SUPPORTED_SAFARI_VERSION) {
      const url = req.nextUrl.clone();
      url.pathname = '/supported-browsers';
      return NextResponse.redirect(url);
    }
  }

  return NextResponse.next();
}

