from typing import List, Dict

def parse_invoice_text(text: str) -> Dict[str, str]:
    """
    Extracts basic fields from raw invoice text.
    """
    data = {}

    # Simple regex for common fields
    invoice_no = re.search(r"Invoice\s*(?:No|#)[:\s]*(\w+)", text, re.I)
    if invoice_no:
        data['invoice_number'] = invoice_no.group(1)

    amount = re.search(r"Total[:\s]*\$?([\d,]+\.\d{2})", text, re.I)
    if amount:
        data['total_amount'] = amount.group(1).replace(',', '')

    date = re.search(r"Date[:\s]*(\d{2}/\d{2}/\d{4})", text)
    if date:
        data['date'] = date.group(1)

