export function getBrowser(ua: string) {
  const isSafari = /Safari/.test(ua) && !/Chrome/.test(ua);
  const isChrome = /Chrome/.test(ua);
  const isFirefox = /Firefox/.test(ua);

  let version = "0";
  const match = ua.match(/(Version|Chrome|Firefox|Edge)\/(\d+\.?\d*)/);
  if (match) version = match[2];

  return {
    name: isSafari ? "Safari" : isChrome ? "Chrome" : isFirefox ? "Firefox" : "Unknown",
    version: parseFloat(version),
    isMobile: /Mobile|Android|iPhone/.test(ua)
  };
}

export function isSupported(ua: string): boolean {
  const { name, version } = getBrowser(ua);
  if (name === "Safari") return version >= 17;
  if (name === "Chrome") return version >= 110;
  if (name === "Firefox") return version >= 105;
  return true;
}

