export interface CartItem {
  id: string;
  sku: string;
  name: string;
  price: number;
  quantity: number;
  metadata?: Record<string, any>;
}

export interface CartState {
  items: CartItem[];
  currency: string;
  updatedAt: number;
}

export const $cart = atom<CartState>({
  items: [],
  currency: 'USD',
  updatedAt: Date.now(),
});

export function addItem(item: CartItem) {
  const current = $cart.get();
  $cart.set({
    ...current,
    items: [...current.items, item],
    updatedAt: Date.now(),
  });
}

export function removeItem(id: string) {
  const current = $cart.get();
  $cart.set({
    ...current,
    items: current.items.filter(i => i.id !== id),
    updatedAt: Date.now(),
  });
}

export function clearCart() {
  $cart.set({
    items: [],
    currency: 'USD',
    updatedAt: Date.now(),
  });
}

