--- src/matcher.py
def match_invoice_to_po(invoice, pos):
    """
    Matches an invoice against a list of purchase orders.
    Basic logic: match by ID and total amount.
    """
    invoice_id = invoice.get('id')
    amount = invoice.get('amount')

    for po in pos:
        if po.get('id') == invoice_id and po.get('total') == amount:
            return {"match": True, "po_id": po.get('id'), "confidence": 1.0}

    return {"match": False, "po_id": None, "confidence": 0.0}
