        raise FileNotFoundError(f"Task config not found: {task_path}")

    # Provider dispatch logic
    if provider == "gateway":
        from providers.gateway import call_gateway
        return call_gateway(model, task_path, seed)
    elif provider == "vertex":
        from providers.vertex import call_vertex
        return call_vertex(model, task_path, seed)
    else:
        raise ValueError(f"Unsupported provider: {provider}")

