import { getFlags } from '../lib/unleash';
import { NEW_TIERS, LEGACY_TIERS } from '../pricing/constants';

export async function POST(req: Request) {
  const body = await req.json();
  const { tier, userId } = body;
  const flags = await getFlags(userId);

  let pricingData;
  if (flags.isEnabled('new-pricing')) {
    pricingData = NEW_TIERS[tier];
  } else {
    pricingData = LEGACY_TIERS[tier];
  }

  if (!pricingData) {
    return new Response('Invalid tier', { status: 400 });
  }

  try {
    const session = await stripe.checkout.sessions.create({
      payment_method_types: ['card'],
      line_items: [
        {
          price_data: {
            currency: 'usd',
            product_data: {
              name: `${tier.toUpperCase()} Plan`,
            },
            unit_amount: Math.round(pricingData.price * 100),
          },
          quantity: 1,
        },
      ],
      mode: 'subscription',
      success_url: `${process.env.BASE_URL}/success?session_id={CHECKOUT_SESSION_ID}`,
      cancel_url: `${process.env.BASE_URL}/pricing`,
      metadata: {
        userId,
        tier,
        version: flags.isEnabled('new-pricing') ? 'v2' : 'v1'
      }
    });

    return new Response(JSON.stringify({ url: session.url }), {
      status: 200,
      headers: { 'Content-Type': 'application/json' }
    });
  } catch (err) {
    console.error('Checkout error:', err);
    return new Response('Internal Server Error', { status: 500 });
  }
}

