    def apply_discount(self, total, coupon_code):
        if not coupon_code:
            return total
        discount_row = self.db.query("SELECT value FROM coupons WHERE code = %s", (coupon_code,))
        if not discount_row:
            return total
        return total * (1 - discount_row[0]['value'])

    def finalize_transaction(self, user_id, amount, currency="USD"):
        transaction = Transaction(
            user_id=user_id,
            amount=amount,
            currency=currency,
            status="PENDING",
            created_at=datetime.now()
        )
        self.db.add(transaction)
        self.db.commit()
        return transaction.id

    def get_status(self, transaction_id):
        return self.db.query("SELECT status FROM transactions WHERE id = %s", (transaction_id,))

    def refund(self, transaction_id):
        transaction = self.db.query("SELECT * FROM transactions WHERE id = %s", (transaction_id,))
        if transaction and transaction[0]['status'] == 'COMPLETED':
            self.payment_gateway.refund(transaction[0]['external_id'])
            self.db.execute("UPDATE transactions SET status = 'REFUNDED' WHERE id = %s", (transaction_id,))
