import datetime
from decimal import Decimal

def format_currency(amount: Decimal, currency: str = "USD") -> str:
    """Formats a decimal amount as a currency string."""
    return f"{currency} {amount:,.2f}"

def parse_date(date_str: str) -> datetime.date:
    """Parses standard ISO dates used in billing records."""
    try:
        return datetime.date.fromisoformat(date_str)
    except ValueError:
        # Fallback for common legacy formats
        return datetime.datetime.strptime(date_str, "%m/%d/%Y").date()

def get_billing_period(date: datetime.date) -> str:
    """Returns the YYYY-MM string for a given date."""
    return date.strftime("%Y-%m")

def validate_vendor_id(vendor_id: str) -> bool:
    """Basic check for vendor ID format."""
    return vendor_id.isalnum() and len(vendor_id) >= 4

