export async function submitCheckout() {
    const submitBtn = document.getElementById('submit-checkout');
    if (!submitBtn) return;

    submitBtn.addEventListener('click', async () => {
        // Sort items by ID to ensure deterministic order for backend
        const sortedItems = cart.items.toSorted((a, b) => a.id.localeCompare(b.id));

