import { cart } from "../store/cart";
import { validateCart } from "./validation";

export async function handleCheckoutSubmit(e: SubmitEvent) {
    e.preventDefault();
    const submitButton = e.target as HTMLButtonElement;
    submitButton.disabled = true;

    try {
        // Ensure items are ordered for consistent hashing
        const items = cart.items.toSorted((a, b) => a.id.localeCompare(b.id));
        const payload = {
            items,
            timestamp: Date.now()
        };

        const res = await fetch('/api/checkout/submit', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload)
        });

        if (res.ok) {
            window.location.href = '/checkout/success';
        } else {
            throw new Error('Submission failed');
        }
    } catch (err) {
        console.error("Checkout error:", err);
        submitButton.disabled = false;
    }
}

