/**
 * Checks if the current Safari version meets the minimum requirements
 * defined by the product decision (2026-Q3).
 */
export function isSafariSupported(ua: string): boolean {
  const match = ua.match(/Version\/(\d+)(\.\d+)*.*Safari/);
  if (match) {
    const majorVersion = parseInt(match[1], 10);
    return majorVersion >= SUPPORTED_SAFARI_VERSION;
  }
  return true;
}

export const SUPPORT_URL = "/supported-browsers";

export function handleUnsupportedBrowser(): void {
