export interface UserAgentInfo {
  browser: string;
  version: string;
  os: string;
}

/**
 * Basic UA parser for internal logging and support routing.
 */
export function parseUA(ua: string): UserAgentInfo {
  const browserMatch = ua.match(/(firefox|chrome|safari|edg)\/([\d.]+)/i) || [];
  const osMatch = ua.match(/\(([^)]+)\)/) || [];

  return {
    browser: browserMatch[1] || 'Unknown',
    version: browserMatch[2] || '0.0.0',
    os: osMatch[1] || 'Unknown'
  };
}

/**
 * Checks if the browser meets the minimum requirements defined in .browserslistrc
 */
export function isLegacySafari(ua: string): boolean {
  const info = parseUA(ua);
  if (info.browser.toLowerCase() === 'safari') {
    const majorVersion = parseInt(info.version.split('.')[0], 10);
    return majorVersion < 17;
  }
  return false;
}

