import { useEffect } from 'react';

/**
 * Hook to verify browser compatibility.
 * Redirects to /supported-browsers if the user agent does not meet
 * the minimum requirements defined in the product support matrix.
 */
export function useBrowserCheck() {
  useEffect(() => {
    const isSafari = /^((?!chrome|android).)*safari/i.test(navigator.userAgent);
    const match = navigator.userAgent.match(/Version\/(\d+)/);
    const safariVersion = match ? parseInt(match[1], 10) : null;

    if (isSafari && safariVersion && safariVersion < 17) {
      // Safari < 17 is unsupported as per Product Decision 2026-Q3
      if (window.location.pathname !== '/supported-browsers') {
        window.location.href = '/supported-browsers';
      }
    }
  }, []);
}

