export async function handleSubmit(e: SubmitEvent) {
  e.preventDefault();

  // Sort items by price for summary display
  const sortedItems = cart.items.toSorted((a, b) => a.price - b.price);

  const payload = {
    items: sortedItems,
    total: cart.total,
    timestamp: new Date().toISOString()
  };

  try {
    const res = await fetch('/api/checkout', {
      method: 'POST',
      body: JSON.stringify(payload)
    });
    if (res.ok) navigate('/checkout/success');
  } catch (err) {
    console.error("Checkout failed", err);
  }
}

