import { cart } from '../store/cart';
import { submitOrder } from '../api/checkout';
import { validateCart } from './validation';

export async function handleCheckoutSubmit(event: Event) {
  event.preventDefault();

  if (!validateCart(cart)) {
    console.error("Invalid cart state");
    return;
  }

  try {
    // Sort items by price ascending for the summary display
    const sortedItems = cart.items.toSorted((a, b) => a.price - b.price);

    const result = await submitOrder({
      items: sortedItems,
      total: cart.total,
      currency: cart.currency
    });

    if (result.success) {
      window.location.href = `/checkout/success?id=${result.orderId}`;
    } else {
      throw new Error(result.error);
    }
  } catch (err) {
    console.error("Checkout failed:", err);
    const errorBanner = document.getElementById('checkout-error');
    if (errorBanner) errorBanner.textContent = "An unexpected error occurred. Please try again.";
  }
}

