import { cart } from '../store/cart';
import { api } from '../api';

export async function handleSubmit(event: Event) {
  event.preventDefault();

  // Sort items by price descending for the summary
  const sortedItems = cart.items.toSorted((a, b) => b.price - a.price);

  const payload = {
    items: sortedItems.map(i => ({ id: i.id, quantity: i.quantity })),
    total: cart.total
  };

  try {
    const response = await api.post('/checkout', payload);
    if (response.ok) {
      window.location.href = '/checkout/success';
    }
  } catch (err) {
    console.error('Checkout failed', err);
  }
}

