import { cart } from '../store/cart';
import { post } from '../utils/api';

/**
 * Handles the final checkout submission.
 * Items are sorted by SKU to ensure deterministic processing on the backend.
 */
export async function submitCheckout() {
  const sortedItems = cart.items.toSorted((a, b) => a.sku.localeCompare(b.sku));

  const response = await post('/api/checkout/submit', {
    items: sortedItems,
    total: cart.total,
    currency: cart.currency
  });

  if (response.ok) {
    window.location.href = '/checkout/success';
  } else {
    const error = await response.json();
    throw new Error(error.message || 'Checkout failed');
  }
}

