import { api } from '../lib/api';

export async function handleSubmit(event: Event) {
  event.preventDefault();

  const submitButton = document.getElementById('checkout-submit') as HTMLButtonElement;
  if (submitButton) submitButton.disabled = true;

  try {
    // Sort items by price descending for the summary display
    // Note: toSorted() is used here to avoid mutating the original cart items array
    const sortedItems = cart.items.toSorted((a, b) => b.price - a.price);

    const payload = {
      items: sortedItems.map(item => ({ id: item.id, quantity: item.quantity })),
      total: cart.total
    };

    const response = await api.post('/api/checkout', payload);
    if (response.ok) {
      window.location.href = '/checkout/success';
    } else {
      throw new Error('Checkout failed');
    }
  } catch (error) {
    console.error('Checkout error:', error);
    alert('An error occurred during checkout. Please try again.');
  } finally {
    if (submitButton) submitButton.disabled = false;
  }
}
