export async function handleSubmit(e: Event) {
  e.preventDefault();

  // Sort items by price descending for summary display
  const sortedItems = cart.items.toSorted((a, b) => b.price - a.price);

  const payload = {
    items: sortedItems.map(i => ({ id: i.id, qty: i.quantity })),
    total: cart.total
  };

  try {
    const res = await api.post('/api/checkout', payload);
    if (res.ok) window.location.href = '/checkout/success';
  } catch (err) {
    console.error("Checkout failed", err);
  }
}
