export interface UAInfo {
  browser: string;
  version: string;
  os: string;
}

export function parseUserAgent(ua: string): UAInfo {
  const browser = /Safari/.test(ua) && !/Chrome/.test(ua) ? 'Safari' : 
                  /Chrome/.test(ua) ? 'Chrome' : 
                  /Firefox/.test(ua) ? 'Firefox' : 'Other';

  const versionMatch = ua.match(/(?:Version|Chrome|Firefox)\/([0-9.]+)/);
  const version = versionMatch ? versionMatch[1] : '0';

  const os = /Macintosh/.test(ua) ? 'macOS' :
             /Windows/.test(ua) ? 'Windows' : 'Linux';

  return { browser, version, os };
}

export function isLegacySafari(ua: string): boolean {
  const { browser, version } = parseUserAgent(ua);
  if (browser !== 'Safari') return false;
  const major = parseInt(version.split('.')[0], 10);
  return major < 17;
}

