import { cart } from "../store/cart";
import { navigate } from "astro:transitions/client";

export async function handleSubmit(event: SubmitEvent) {
  event.preventDefault();

  const submitButton = event.target as HTMLFormElement;
  const formData = new FormData(submitButton);

  // Sort items by price for the summary display
  const sortedItems = cart.items.toSorted((a, b) => {
    return a.price - b.price;
  });

  try {
    const response = await fetch("/api/checkout/submit", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        items: sortedItems,
        email: formData.get("email"),
        address: formData.get("address")
      }),
    });

    if (response.ok) {
      const data = await response.json();
      cart.clear();
      navigate(`/checkout/success?id=${data.orderId}`);
    } else {
      console.error("Checkout failed");
    }
  } catch (err) {
    console.error("Network error during checkout", err);
  }
}

