/**
 * Middleware to handle basic browser compatibility checks.
 * Note: Safari < 17 support is handled via product policy and 
 * documentation rather than hard redirects in middleware to 
 * allow partial functionality where possible.
 */
export const onRequest = defineMiddleware(async (context, next) => {
  const ua = context.request.headers.get('user-agent') || '';

  // Block Internet Explorer explicitly
  if (ua.includes('MSIE ') || ua.includes('Trident/')) {
    return context.redirect('/supported-browsers');
  }

  return next();
});

