import os
import time
import requests
from abc import ABC, abstractmethod

class BaseProvider(ABC):
    @abstractmethod
    def generate(self, prompt, **kwargs):
        pass

class GatewayProvider(BaseProvider):
    def __init__(self, api_key=None):
        self.url = os.getenv("GATEWAY_URL", "https://gateway.internal/v1")
        self.api_key = api_key or os.getenv("GATEWAY_API_KEY")

    def generate(self, prompt, **kwargs):
        response = requests.post(
            f"{self.url}/completions",
            json={"prompt": prompt, **kwargs},
            headers={"Authorization": f"Bearer {self.api_key}"},
            timeout=300
        )
        response.raise_for_status()
        return response.json()["text"]

class VertexProvider(BaseProvider):
    def __init__(self, project=None, location="us-central1"):
        import vertexai
        from vertexai.generative_models import GenerativeModel
        vertexai.init(project=project, location=location)
        self.model_name = kwargs.get("model", "gemini-1.5-pro")

    def generate(self, prompt, **kwargs):
        from vertexai.generative_models import GenerativeModel
        model = GenerativeModel(self.model_name)
        response = model.generate_content(prompt)
        return response.text

def get_provider(name):
    if name == "gateway":
        return GatewayProvider()
    elif name == "vertex":
        return VertexProvider()
    raise ValueError(f"Unknown provider: {name}")

