def get_failed_cells(campaign_dir):
    failed = []
    for root, dirs, files in os.walk(campaign_dir):
        if "results.json" in files:
            try:
                with open(os.path.join(root, "results.json")) as f:
                    data = json.load(f)
                    if data.get("completed_runs", 0) < data.get("total_runs", 10):
                        rel_path = os.path.relpath(root, campaign_dir)
                        failed.append(rel_path)
            except (json.JSONDecodeError, IOError):
                rel_path = os.path.relpath(root, campaign_dir)
                failed.append(rel_path)
    return failed

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--campaign", required=True)
    parser.add_argument("--dry-run", action="store_true")
    args = parser.parse_args()

    campaign_path = os.path.join("runs", args.campaign)
    if not os.path.exists(campaign_path):
        print(f"Campaign directory {campaign_path} not found.")
        return

    failed = get_failed_cells(campaign_path)

    if not failed:
        print("No failed cells found.")
        return

    print(f"Found {len(failed)} failed cells in {args.campaign}: {', '.join(failed)}")

    cmd = ["python", "run.py", "--campaign", args.campaign, "--cells"] + failed
    if args.dry_run:
        print(f"Dry run: {' '.join(cmd)}")
    else:
        print(f"Executing: {' '.join(cmd)}")
        subprocess.run(cmd, check=True)

if __name__ == "__main__":
