from typing import Any, Dict, List

class GatewayProvider:
    def __init__(self, api_key: str = None, base_url: str = None):
        self.api_key = api_key or os.getenv("GATEWAY_API_KEY")
        self.base_url = base_url or os.getenv("GATEWAY_BASE_URL", "https://api.internal-gateway.net/v1")
        self.timeout = 60

    def generate(self, model: str, messages: List[Dict[str, str]], **kwargs) -> str:
        payload = {
            "model": model,
            "messages": messages,
            **kwargs
        }
        headers = {
            "Authorization": f"Bearer {self.api_key}",
            "Content-Type": "application/json"
        }

        try:
            response = requests.post(
                f"{self.base_url}/chat/completions",
                json=payload,
                headers=headers,
                timeout=self.timeout
            )
            response.raise_for_status()
            return response.json()["choices"][0]["message"]["content"]
        except requests.exceptions.Timeout:
            # Log timeout for debugging
            print(f"Gateway timeout for model {model}")
            raise
        except Exception as e:
            print(f"Gateway error: {e}")
            raise

    def get_status(self) -> Dict[str, Any]:
        response = requests.get(f"{self.base_url}/health")
        return response.json()

import yaml
import os
from dataclasses import dataclass
from typing import Dict, Any

@dataclass
class Task:
    name: str
    config: Dict[str, Any]
    hash: str

def load_task(task_path: str) -> Task:
    with open(task_path, 'r') as f:
        config = yaml.safe_load(f)

    # Simple hash for comparison
    import hashlib
    content = yaml.dump(config, sort_keys=True).encode('utf-8')
    task_hash = hashlib.sha256(content).hexdigest()

    return Task(
        name=os.path.splitext(os.path.basename(task_path))[0],
        config=config,
        hash=task_hash
    )

def get_all_tasks(tasks_dir: str = "tasks") -> Dict[str, Task]:
    tasks = {}
    for filename in os.listdir(tasks_dir):
        if filename.endswith(".yaml"):
            path = os.path.join(tasks_dir, filename)
            task = load_task(path)
            tasks[task.name] = task
    return tasks

