import json
import os
import argparse
from typing import List, Dict

def load_results(path: str) -> List[Dict]:
    if not os.path.exists(path):
        return []
    with open(path, 'r') as f:
        return [json.loads(line) for line in f]

def score_response(response: str, reference: str) -> float:
    # Basic exact match or substring check for the harness
    return 1.0 if reference.strip() in response else 0.0

def evaluate_cell(cell_path: str):
    results_path = os.path.join(cell_path, "results.jsonl")
    results = load_results(results_path)

    scores = []
    for entry in results:
        score = score_response(entry["output"], entry["reference"])
        scores.append(score)

    if not scores:
        return 0.0
    return sum(scores) / len(scores)

if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("--path", type=str, help="Path to the cell or campaign directory")
    args = parser.parse_args()

    if os.path.isdir(args.path):
        score = evaluate_cell(args.path)
        print(f"Mean score for {args.path}: {score:.4f}")

