from pathlib import Path

def analyze_campaign(campaign_path, table=False):
    path = Path(campaign_path)
    manifest_path = path / "manifest.json"
    if not manifest_path.exists():
        print(f"Error: {manifest_path} not found")
        return

    with open(manifest_path) as f:
        manifest = json.load(f)

    results = []
    for task_dir in path.glob("T*"):
        if not task_dir.is_dir():
            continue
        for seed_dir in task_dir.glob("seed*"):
            run_file = seed_dir / "results.json"
            if run_file.exists():
                with open(run_file) as f:
                    data = json.load(f)
                    results.append({
                        "task": task_dir.name,
                        "seed": seed_dir.name,
                        "status": "complete",
                        "score": data.get("score", 0)
                    })
            else:
                results.append({
                    "task": task_dir.name,
                    "seed": seed_dir.name,
                    "status": "incomplete",
                    "score": 0
                })

    if table:
        print(f"# Campaign Analysis: {manifest.get('model')}")
        print(f"| Task | Seed | Status | Score |")
        print(f"| :--- | :--- | :--- | :--- |")
        for res in sorted(results, key=lambda x: (x['task'], x['seed'])):
            print(f"| {res['task']} | {res['seed']} | {res['status']} | {res['score']:.3f} |")

if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("campaign_path")
    parser.add_argument("--table", action="store_true")
    args = parser.parse_args()
    analyze_campaign(args.campaign_path, args.table)

