import requests
import time
import os

class GatewayClient:
    def __init__(self, api_key=None, base_url="https://gateway.internal/v1"):
        self.api_key = api_key or os.getenv("GATEWAY_API_KEY")
        self.base_url = base_url
        self.timeout = 300

    def generate(self, model, prompt, **kwargs):
        headers = {
            "Authorization": f"Bearer {self.api_key}",
            "Content-Type": "application/json"
        }
        payload = {
            "model": model,
            "prompt": prompt,
            **kwargs
        }

        try:
            response = requests.post(
                f"{self.base_url}/completions",
                json=payload,
                headers=headers,
                timeout=self.timeout
            )
            response.raise_for_status()
            return response.json()
        except requests.exceptions.Timeout:
            # Logged on 2026-09-19 for campaign-a T2 cells
            print(f"Error: Gateway timeout for model {model}")
            raise
        except requests.exceptions.RequestException as e:
            print(f"Error: Gateway request failed: {e}")
            raise

    def check_health(self):
        try:
            resp = requests.get(f"{self.base_url}/health", timeout=5)
            return resp.status_code == 200
        except:
            return False

