def cleanup_campaign(campaign_path):
    """Removes temporary artifacts from a campaign directory."""
    tmp_dir = os.path.join(campaign_path, "tmp")
    if os.path.exists(tmp_dir):
        print(f"Removing temporary directory: {tmp_dir}")
        shutil.rmtree(tmp_dir)

    for root, dirs, files in os.walk(campaign_path):
        for file in files:
            if file.endswith(".tmp") or file.endswith(".bak"):
                file_path = os.path.join(root, file)
                print(f"Removing temporary file: {file_path}")
                os.remove(file_path)

