import argparse
import json
import os
import sys
from pathlib import Path

def analyze_campaign(campaign_dir):
    manifest_path = os.path.join(campaign_dir, "manifest.json")
    if not os.path.exists(manifest_path):
        print(f"Error: Manifest not found in {campaign_dir}", file=sys.stderr)
        return None

    with open(manifest_path, 'r') as f:
        manifest = json.load(f)

    stats = []
    campaign_path = Path(campaign_dir)
    for task_path in campaign_path.iterdir():
        if not task_path.is_dir() or task_path.name.startswith('.'):
            continue

        for seed_path in task_path.iterdir():
            if not seed_path.is_dir():
                continue

            runs = list(seed_path.glob("run_*.json"))
            stats.append({
                "task": task_path.name,
                "seed": seed_path.name,
                "count": len(runs)
            })

    return {"manifest": manifest, "stats": stats}

def print_table(data):
    print(f"Campaign: {data['manifest'].get('model', 'unknown')}")
    print("| Task | Seed | Completed Runs |")
    print("| :--- | :--- | :--- |")
    for entry in sorted(data['stats'], key=lambda x: (x['task'], x['seed'])):
        print(f"| {entry['task']} | {entry['seed']} | {entry['count']} |")

if __name__ == "__main__":
    parser = argparse.ArgumentParser(description="Analyze campaign results")
    parser.add_argument("campaign_dir", help="Path to the campaign directory")
    parser.add_argument("--table", action="store_true", help="Output as markdown table")

    args = parser.parse_args()
    results = analyze_campaign(args.campaign_dir)

    if results and args.table:
        print_table(results)
    elif results:
        print(json.dumps(results, indent=2))

