import os
import json
import pandas as pd
from pathlib import Path

def load_manifest(campaign_path):
    manifest_path = Path(campaign_path) / "manifest.json"
    with open(manifest_path, 'r') as f:
        return json.load(f)

def aggregate_results(campaign_path):
    results = []
    campaign_dir = Path(campaign_path)
    manifest = load_manifest(campaign_path)

    for task_dir in campaign_dir.iterdir():
        if not task_dir.is_dir() or task_dir.name.startswith('.'):
            continue
        for seed_dir in task_dir.iterdir():
            summary_file = seed_dir / "summary.json"
            if summary_file.exists():
                with open(summary_file, 'r') as f:
                    data = json.load(f)
                    data.update({
                        "task": task_dir.name,
                        "seed": seed_dir.name,
                        "model": manifest.get("model")
                    })
                    results.append(data)
    return pd.DataFrame(results)

def generate_markdown_table(df):
    if df.empty:
        return "No results found."
    return df.groupby(['task', 'model'])['score'].mean().to_markdown()

if __name__ == "__main__":
    import sys
    if len(sys.argv) > 1:
        df = aggregate_results(sys.argv[1])
        print(generate_markdown_table(df))

