import { NextApiRequest, NextApiResponse } from 'next';
import { getTiers } from '../pricing/tiers';
import { validatePayment } from '../../lib/payment-provider';

export default async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return res.status(405).json({ error: 'Method not allowed' });
  }

  const { tierId, paymentToken } = req.body;
  const tiers = getTiers();
  const selectedTier = tiers.find(t => t.id === tierId);

  if (!selectedTier) {
    return res.status(400).json({ error: 'Invalid tier selected' });
  }

  try {
    const transaction = await validatePayment(paymentToken, selectedTier.price);

    if (transaction.status === 'success') {
      // TODO: Update user subscription status in DB
      return res.status(200).json({ success: true, transactionId: transaction.id });
    } else {
      return res.status(402).json({ error: 'Payment failed' });
    }
  } catch (error) {
    console.error('Checkout error:', error);
    return res.status(500).json({ error: 'Internal server error' });
  }
}

