import { getTiers } from '../pricing/tiers';
import { logger } from '../utils/logger';

export async function initializeSession(userId: string, selectedTierId: string) {
  const tiers = getTiers();
  const tier = tiers.find(t => t.id === selectedTierId);

  if (!tier) {
    logger.error(`Session initialization failed: Tier ${selectedTierId} not found`);
    throw new Error('Invalid pricing tier selected');
  }

  logger.info(`Initializing checkout session for user ${userId} on tier ${tier.id}`);

  return {
    sessionId: crypto.randomUUID(),
    tierId: tier.id,
    price: tier.price,
    currency: 'USD',
    createdAt: new Date().toISOString()
  };
}

export function validateSession(session: any) {
  const now = new Date();
  const sessionDate = new Date(session.createdAt);
  const diffMinutes = (now.getTime() - sessionDate.getTime()) / 60000;

  return diffMinutes < 30;
}

