import { Request, Response } from 'express';
import { getTiers } from '../../web/pricing/tiers';
import { stripe } from '../lib/stripe';
import { logger } from '../lib/logger';

/**
 * Creates a Stripe Checkout session for the selected pricing tier.
 * The tier details are retrieved via getTiers(), which respects
 * the 'new-pricing' Unleash feature flag.
 */
export async function createCheckoutSession(req: Request, res: Response) {
  try {
    const { tierId, customerEmail } = req.body;

    if (!tierId) {
      return res.status(400).json({ error: 'tierId is required' });
    }

    const availableTiers = getTiers();
    const selectedTier = availableTiers.find(t => t.id === tierId);

    if (!selectedTier) {
      logger.warn(`Attempted checkout with invalid tierId: ${tierId}`);
      return res.status(404).json({ error: 'Pricing tier not found' });
    }

    const session = await stripe.checkout.sessions.create({
      customer_email: customerEmail,
      payment_method_types: ['card'],
      line_items: [
        {
          price: selectedTier.stripePriceId,
          quantity: 1,
        },
      ],
      mode: 'subscription',
      success_url: `${process.env.APP_URL}/dashboard?session_id={CHECKOUT_SESSION_ID}`,
      cancel_url: `${process.env.APP_URL}/pricing`,
      metadata: {
        tierId: selectedTier.id,
        version: 'v2'
      },
    });

    return res.status(200).json({ sessionId: session.id, url: session.url });
  } catch (error) {
    logger.error('Failed to create checkout session', error);
    return res.status(500).json({ error: 'Internal server error' });
  }
}

