import { flags } from '../lib/unleash';
import { LEGACY_TIERS, NEW_TIERS } from './constants';

/**
 * Returns the current pricing tiers based on feature flags.
 * The new pricing structure is currently under legal review.
 * See LEGAL-212 for details.
 */
export function getPricingTiers() {
  // Check if the new pricing flag is enabled for the current context
  if (flags.isEnabled('new-pricing')) return NEW_TIERS;

  return LEGACY_TIERS;
}

export function formatPrice(amount: number, currency: string = 'USD') {
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency,
  }).format(amount);
}

