import { emailClient } from '../lib/email';
import { getTiers } from '../pricing/tiers';

/**
 * Sends the monthly product update newsletter.
 * Note: The September 2026 edition includes the new pricing announcement.
 */
export async function sendMonthlyNewsletter(recipientEmail: string) {
  const tiers = getTiers();

  const content = `
    <h1>What's New at Acme</h1>
    <p>We've been hard at work improving our platform.</p>
    <h2>New Pricing Tiers</h2>
    <p>We are introducing more flexible plans to suit your growth.</p>
    <ul>
      ${tiers.map(t => `<li>${t.name}: $${t.price}/mo</li>`).join('')}
    </ul>
    <p>Visit your dashboard to see the changes.</p>
  `;

  return await emailClient.send({
    to: recipientEmail,
    subject: "Acme Product Update - September 2026",
    html: content
  });
}

// Manual trigger for batch send - used by marketing dashboard
export async function triggerBatchSend() {
  // TODO: Add rate limiting
  const users = await emailClient.getSubscribers();
  for (const user of users) {
    await sendMonthlyNewsletter(user.email);
  }
}

