import { unleash } from '../../lib/unleash';
import { getTiers } from '../pricing/tiers';
import { stripe } from '../../lib/stripe';

export default async function handler(req, res) {
  if (req.method !== 'POST') {
    return res.status(405).end();
  }

  const { planId, customerEmail } = req.body;

  // Check feature flags for pricing version
  const isNewPricing = unleash.isEnabled('new-pricing');
  const tiers = getTiers();
  const plan = tiers.find(t => t.id === planId);

  if (!plan) {
    return res.status(400).json({ error: 'Invalid plan selection' });
  }

  try {
    const session = await stripe.checkout.sessions.create({
      customer_email: customerEmail,
      payment_method_types: ['card'],
      line_items: [
        {
          price: plan.stripePriceId,
          quantity: 1,
        },
      ],
      mode: 'subscription',
      success_url: `${process.env.APP_URL}/dashboard?session_id={CHECKOUT_SESSION_ID}`,
      cancel_url: `${process.env.APP_URL}/pricing`,
      metadata: {
        planId,
        pricingVersion: isNewPricing ? '2026-Q3' : 'legacy'
      }
    });

    return res.status(200).json({ sessionId: session.id });
  } catch (err) {
    console.error('Stripe session error:', err);
    return res.status(500).json({ error: 'Failed to create checkout session' });
  }
}

