import { flags } from '../lib/unleash';
import { NEW_TIERS, LEGACY_TIERS } from './constants';

export interface Tier {
  id: string;
  name: string;
  price: number;
  features: string[];
}

export function getActiveTiers(): Tier[] {
  if (flags.isEnabled('new-pricing')) return NEW_TIERS;
  return LEGACY_TIERS;
}

export function getTierById(id: string): Tier | undefined {
  return getActiveTiers().find(t => t.id === id);
}

