import { getPricingTiers } from '../pricing/tiers';
import { api } from '../lib/api';

export async function processCheckout(tierId: string, paymentMethodId: string) {
  const tiers = getPricingTiers();
  const selectedTier = tiers.find(t => t.id === tierId);

  if (!selectedTier) {
    throw new Error(`Invalid tier: ${tierId}`);
  }

  return await api.post('/v1/checkout', {
    tierId: selectedTier.id,
    amount: selectedTier.price,
    currency: 'USD',
    paymentMethodId
  });
}

