import os

# Marketing Automation Script for Monthly Newsletters
# Usage: python send_newsletter.py <content_file.json>

API_ENDPOINT = "https://api.acme-marketing.internal/v2/broadcast"
API_KEY = os.getenv("MARKETING_SERVICE_KEY")

def send_broadcast(content_path):
    if not API_KEY:
        print("Error: MARKETING_SERVICE_KEY not set.")
        sys.exit(1)

    try:
        with open(content_path, 'r') as f:
            data = json.load(f)

        print(f"Preparing to send: {data.get('subject')}")

        response = requests.post(
            API_ENDPOINT,
            headers={"Authorization": f"Bearer {API_KEY}"},
            json={
                "campaign": data.get("campaign_id"),
                "subject": data.get("subject"),
                "content": data.get("body_html"),
                "target_segment": data.get("segment", "all_users")
            }
        )

        if response.status_code == 202:
            print(f"Success: Broadcast {data.get('campaign_id')} queued.")
        else:
            print(f"Failed: {response.status_code} - {response.text}")

    except FileNotFoundError:
        print(f"Error: File {content_path} not found.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")

if __name__ == "__main__":
    if len(sys.argv) < 2:
        print("Usage: python send_newsletter.py <path_to_json>")
    else:
        send_broadcast(sys.argv[1])

