export class CheckoutProcessor {
  async calculateTotal(cart: any, userId: string) {
    const tiers = getPricingTiers();
    const context = { userId };

    const isNewPricing = unleash.isEnabled('new-pricing', context);

    let total = 0;
    for (const item of cart.items) {
      const price = isNewPricing 
        ? tiers.find(t => t.id === item.tierId)?.price 
        : tiers.find(t => t.id === item.tierId)?.legacyPrice;

      total += (price || 0) * item.quantity;
    }

    return total;
  }

