import logging
import requests

logger = logging.getLogger(__name__)

class InvoiceMatcherClient:
    def __init__(self, base_url, timeout=30):
        self.base_url = base_url.rstrip('/')
        self.timeout = timeout

    def match_invoice(self, invoice_id, transaction_data):
        """
        Sends transaction data to the matching engine for a specific invoice.
        """
        url = f"{self.base_url}/v1/match/{invoice_id}"
        try:
            response = requests.post(url, json=transaction_data, timeout=self.timeout)
            response.raise_for_status()
            return response.json()
        except requests.exceptions.RequestException as e:
            logger.error(f"Failed to match invoice {invoice_id}: {e}")
            raise

    def get_status(self):
        return requests.get(f"{self.base_url}/health", timeout=5).json()

