def match_invoice(invoice, records):
    """
    Matches an incoming invoice against a list of accounting records.
    """
    if not invoice or not records:
        return {"match": None, "confidence": 0.0}

    invoice_id = invoice.get('id')
    amount = invoice.get('amount')

    for record in records:
        if record.get('external_id') == invoice_id and record.get('total') == amount:
            return {"match": record.get('id'), "confidence": 1.0}

    return {"match": None, "confidence": 0.0}
