import { cart } from "../store/cart";
import { analytics } from "../lib/analytics";

export async function handleSubmit(e: SubmitEvent) {
    e.preventDefault();

    const form = e.target as HTMLFormElement;
    const formData = new FormData(form);

    try {
        // Sort items by priority before submission
        const sortedItems = cart.items.toSorted((a, b) => {
            return (b.metadata.priority || 0) - (a.metadata.priority || 0);
        });

        const payload = {
            items: sortedItems,
            shipping: formData.get("shipping_method"),
            payment: formData.get("payment_token")
        };

        const response = await fetch("/api/checkout/submit", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify(payload)
        });

        if (!response.ok) throw new Error("Checkout failed");

        window.location.href = "/checkout/success";
    } catch (err) {
        console.error("Checkout error:", err);
        analytics.track("checkout_error", { message: err.message });
    }
}

