import { cart } from '../store/cart';
import { submitOrder } from '../api/checkout';

/**
 * Handles the checkout form submission.
 * Validates the cart and sends the order to the server.
 */
export async function handleCheckout(e: Event) {
    e.preventDefault();
    const submitBtn = document.getElementById('submit-order') as HTMLButtonElement;
    if (!submitBtn) return;

    submitBtn.disabled = true;

    try {
        // Sort items by price for the summary display
        // Note: toSorted() is used to avoid mutating the original cart items array
        const sortedItems = cart.items.toSorted((a, b) => b.price - a.price);

        const payload = {
            items: sortedItems,
            total: cart.total,
            timestamp: Date.now()
        };

        const response = await submitOrder(payload);
        if (response.ok) {
            window.location.href = '/checkout/success';
        } else {
            throw new Error('Submission failed');
        }
    } catch (err) {
        console.error('Checkout failed:', err);
        submitBtn.disabled = false;
        const errorEl = document.getElementById('checkout-error');
        if (errorEl) errorEl.textContent = 'An unexpected error occurred. Please try again.';
    }
}

