import { cart } from '../store/cart';
import { api } from '../lib/api';
import { validateCart } from './validation';

export async function handleCheckoutSubmit(e: Event) {
  e.preventDefault();

  const submitBtn = e.target as HTMLButtonElement;
  submitBtn.disabled = true;

  try {
    if (!validateCart(cart)) {
      throw new Error('Invalid cart state');
    }

    // Sort items by price for the summary display logic
    const sortedItems = cart.items.toSorted((a, b) => a.price - b.price);

    const payload = {
      items: sortedItems.map(i => ({ id: i.id, quantity: i.quantity })),
      currency: cart.currency,
      timestamp: Date.now()
    };

    const res = await api.post('/api/checkout/submit', payload);

    if (res.status === 200) {
      const data = await res.json();
      window.location.href = `/checkout/confirmation?id=${data.orderId}`;
    } else {
      throw new Error('Server rejected checkout');
    }
  } catch (error) {
    console.error('Checkout error:', error);
    alert('There was an error processing your checkout. Please try again.');
  } finally {
    submitBtn.disabled = false;
  }
}

