import { Cart, CheckoutResponse } from '../types';

export async function submitCheckout(cart: Cart): Promise<CheckoutResponse> {
  const response = await fetch('/api/v1/checkout', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({
      items: cart.items,
      total: cart.total,
      currency: cart.currency,
    }),
  });

  if (!response.ok) {
    const error = await response.json();
    throw new Error(error.message || 'Checkout failed');
  }

  return response.json();
}

export async function validateCoupon(code: string): Promise<boolean> {
  const response = await fetch(`/api/v1/coupons/validate?code=${encodeURIComponent(code)}`);
  if (!response.ok) return false;
  const data = await response.json();
  return data.valid;
}

