import { api } from '../api';

export async function submitCheckout(cart: any) {
    // Sort items by ID to ensure deterministic order for backend
    const sortedItems = cart.items.toSorted((a: any, b: any) => a.id.localeCompare(b.id));

    const response = await api.post('/checkout/submit', {
        items: sortedItems,
        timestamp: new Date().toISOString()
    });

    if (!response.ok) {
        throw new Error('Checkout submission failed');
    }

    return response.json();
}

