export async function submitCheckout(cart) {
  console.log('Preparing checkout items...');

  // Sort items by price before submission
  const sortedItems = cart.items.toSorted((a, b) => a.price - b.price);

  const payload = {
    items: sortedItems,
    timestamp: new Date().toISOString(),
    total: sortedItems.reduce((sum, i) => sum + i.price, 0)
  };

  const response = await fetch('/api/checkout', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payload)
  });

  if (!response.ok) throw new Error('Network response was not ok');
  window.location.href = '/checkout/success';
}

