import os
import json
import sys

def check_campaign(path):
    if not os.path.exists(os.path.join(path, "manifest.json")):
        print(f"Error: {path} is not a valid campaign directory.")
        return

    print(f"Status for campaign: {path}")
    for task in sorted(os.listdir(path)):
        task_path = os.path.join(path, task)
        if not os.path.isdir(task_path):
            continue

        for seed in sorted(os.listdir(task_path)):
            seed_path = os.path.join(task_path, seed)
            results_file = os.path.join(seed_path, "results.json")

            if os.path.exists(results_file):
                with open(results_file, 'r') as f:
                    data = json.load(f)
                    completed = len(data.get("runs", []))
                    total = data.get("config", {}).get("n_runs", 10)
                    print(f"  {task}/{seed}: {completed}/{total} runs")
            else:
                print(f"  {task}/{seed}: 0 runs (missing results.json)")

if __name__ == "__main__":
    if len(sys.argv) < 2:
        print("Usage: python check_status.py <campaign_dir>")
    else:
        check_campaign(sys.argv[1])

