import argparse
import json
import os
import sys
from pathlib import Path

def check_campaign(path, failed_only=False, format='list'):
    manifest_path = Path(path) / "manifest.json"
    if not manifest_path.exists():
        print(f"Error: {manifest_path} not found", file=sys.stderr)
        return 1

    failed_cells = []
    # Walk through task/seed directories
    for task_dir in Path(path).iterdir():
        if not task_dir.is_dir() or task_dir.name.startswith('.'):
            continue
        for seed_dir in task_dir.iterdir():
            if not seed_dir.is_dir():
                continue

            results_file = seed_dir / "results.json"
            cell_id = f"{task_dir.name}/{seed_dir.name}"

            if not results_file.exists():
                failed_cells.append(cell_id)
                continue

            try:
                with open(results_file) as f:
                    data = json.load(f)
                    if len(data.get("runs", [])) == 0:
                        failed_cells.append(cell_id)
            except (json.JSONDecodeError, IOError):
                failed_cells.append(cell_id)

    if format == 'space':
        print(" ".join(failed_cells))
    else:
        for cell in failed_cells:
            print(cell)
    return 0

if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("path")
    parser.add_argument("--failed-only", action="store_true")
    parser.add_argument("--format", choices=['list', 'space'], default='list')
    args = parser.parse_args()
    sys.exit(check_campaign(args.path, args.failed_only, args.format))

