import os
import json
import argparse
from pathlib import Path

def aggregate_campaign(campaign_path):
    path = Path(campaign_path)
    manifest_file = path / "manifest.json"

    if not manifest_file.exists():
        raise FileNotFoundError(f"No manifest found in {campaign_path}")

    with open(manifest_file, 'r') as f:
        manifest = json.load(f)

    aggregated_data = {
        "metadata": manifest,
        "results": {}
    }

    for task_dir in path.glob("T*"):
        task_id = task_dir.name
        aggregated_data["results"][task_id] = {}

        for seed_dir in task_dir.glob("seed*"):
            seed_id = seed_dir.name
            result_path = seed_dir / "result.json"

            if result_path.exists():
                with open(result_path, 'r') as f:
                    aggregated_data["results"][task_id][seed_id] = json.load(f)
            else:
                aggregated_data["results"][task_id][seed_id] = None

    return aggregated_data

if __name__ == "__main__":
    parser = argparse.ArgumentParser(description="Aggregate campaign results into a single JSON.")
    parser.add_argument("campaign_dir", type=str, help="Path to the campaign directory")
    parser.add_argument("--output", type=str, default="summary.json", help="Output filename")

    args = parser.parse_args()

    try:
        summary = aggregate_campaign(args.campaign_dir)
        with open(args.output, 'w') as f:
            json.dump(summary, f, indent=2)
        print(f"Successfully aggregated results to {args.output}")
    except Exception as e:
        print(f"Error: {e}")
        exit(1)

