class Runner:
    VERSION = "2.3.1"

    def __init__(self, campaign_dir: str):
        self.campaign_dir = campaign_dir
        self.manifest = self._load_manifest()
        self.provider = get_provider(
            self.manifest["provider"], 
            model=self.manifest["model"]
        )

    def _load_manifest(self):
        path = os.path.join(self.campaign_dir, "manifest.json")
        with open(path, "r") as f:
            return json.load(f)

    def run_cell(self, task_id: str, seed: int):
        logging.info(f"Running {task_id} (seed={seed}) on {self.manifest['model']}")

        output_path = os.path.join(self.campaign_dir, task_id, f"seed{seed}")
        os.makedirs(output_path, exist_ok=True)

        try:
            result = self.provider.generate(task_id, seed)
            with open(os.path.join(output_path, "result.json"), "w") as f:
                json.dump(result, f, indent=2)
        except Exception as e:
            logging.error(f"Cell {task_id}/seed{seed} failed: {str(e)}")
            with open(os.path.join(output_path, "error.log"), "a") as f:
                f.write(f"{type(e).__name__}: {str(e)}\n")
            raise

    def run_all(self, cells: Optional[List[str]] = None):
        if cells:
            for cell_id in cells:
                task, seed_part = cell_id.split("/")
                seed = int(seed_part.replace("seed", ""))
                self.run_cell(task, seed)
        else:
            # Logic to iterate through all tasks in tasks/ directory
            pass

