/**
 * Fetches pricing tiers and applies any active discounts or promotions.
 * The actual tier selection logic is handled in web/pricing/tiers.ts
 * based on the 'new-pricing' Unleash flag.
 */
export async function fetchPricingDetails() {
  try {
    const tiers = getTiers();
    return {
      success: true,
      tiers: tiers,
      lastUpdated: new Date().toISOString()
    };
  } catch (error) {
    console.error("Failed to fetch pricing tiers:", error);
    return {
      success: false,
      error: "Pricing information is currently unavailable."
    };
  }
}

export function calculateTotal(tierId: string, quantity: number = 1) {
  const tiers = getTiers();
  const selectedTier = tiers.find(t => t.id === tierId);
  if (!selectedTier) return 0;
  return selectedTier.price * quantity;
}

