import React, { useState } from 'react';
import { useFlag } from '@unleash/proxy-client-react';
import { loadStripe } from '@stripe/stripe-js';

const stripePromise = loadStripe(process.env.STRIPE_PUBLIC_KEY!);

export const CheckoutForm: React.FC<{ tierId: string }> = ({ tierId }) => {
  const [loading, setLoading] = useState(false);
  const isNewPricing = useFlag('new-pricing');

  const handleCheckout = async () => {
    setLoading(true);
    const response = await fetch('/api/checkout/session', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ 
        tierId, 
        version: isNewPricing ? 'v2' : 'v1' 
      }),
    });

    const session = await response.json();
    const stripe = await stripePromise;
    const { error } = await stripe!.redirectToCheckout({
      sessionId: session.id,
    });

    if (error) {
      console.error('Stripe checkout error:', error);
      setLoading(false);
    }
  };

  return (
    <div className="checkout-form-container">
      <button
        onClick={handleCheckout}
        disabled={loading}
        className="btn btn-primary"
      >
        {loading ? 'Redirecting...' : 'Subscribe Now'}
      </button>
    </div>
  );
};

import { getPricingTiers } from '../pricing/tiers';
import { stripe } from '../lib/stripe';

export async function createCheckoutSession(tierId: string, userId: string) {
  const tiers = getPricingTiers();
  const selectedTier = tiers.find(t => t.id === tierId);

  if (!selectedTier) {
    throw new Error(`Invalid tier: ${tierId}`);
  }

  // The pricing tiers are determined by the Unleash flag in tiers.ts
  // This ensures the checkout uses the correct Stripe price ID.
  const session = await stripe.checkout.sessions.create({
    payment_method_types: ['card'],
    line_items: [{
      price: selectedTier.stripePriceId,
      quantity: 1,
    }],
    mode: 'subscription',
    success_url: `${process.env.NEXT_PUBLIC_BASE_URL}/success`,
    cancel_url: `${process.env.NEXT_PUBLIC_BASE_URL}/pricing`,
    metadata: {
      userId,
      tierId: selectedTier.id,
      tierName: selectedTier.name
    }
  });

  return { url: session.url };
}

export async function getSubscriptionStatus(userId: string) {
  const subscriptions = await stripe.subscriptions.list({
    customer: userId,
    status: 'active',
    limit: 1
  });
  return subscriptions.data[0];
}

