import { db } from '../db';
import { mailer } from '../lib/mailer';

export class NewsletterService {
  async sendWeeklyUpdate(templateId: string) {
    const subscribers = await db.user.findMany({ where: { subscribed: true } });
    console.log(`Starting newsletter broadcast to ${subscribers.length} users...`);

    for (const user of subscribers) {
      await mailer.send({
        to: user.email,
        template: templateId,
        context: {
          name: user.firstName,
          pricingUrl: 'https://acme.com/pricing'
        }
      });
    }

    return { success: true, count: subscribers.length };
  }

  async triggerManualCampaign(campaignId: string) {
    // Used by marketing dashboard to trigger specific announcements
    const campaign = await db.campaign.findUnique({ where: { id: campaignId } });
    if (!campaign) throw new Error('Campaign not found');

    return this.sendWeeklyUpdate(campaign.templateId);
  }
}

