import { getTiers } from '../pricing/tiers';
import { flags } from '../lib/unleash';

export interface CartItem {
  id: string;
  tierId: string;
  quantity: number;
}

export const calculateTotal = (items: CartItem[]) => {
  const currentTiers = getTiers();
  return items.reduce((total, item) => {
    const tier = currentTiers.find(t => t.id === item.tierId);
    if (!tier) {
      console.warn(`Tier ${item.tierId} not found during checkout`);
      return total;
    }
    return total + (tier.price * item.quantity);
  }, 0);
};

export const validateCart = (items: CartItem[]) => {
  if (items.length === 0) return false;
  return items.every(item => item.quantity > 0);
};

export const checkout = async (cartId: string, items: CartItem[]) => {
  const total = calculateTotal(items);
  const isNewPricing = flags.isEnabled('new-pricing');

  return await fetch('/api/checkout', {
    method: 'POST',
    body: JSON.stringify({
      cartId,
      items,
      total,
      metadata: {
        pricingVersion: isNewPricing ? 'v2' : 'v1'
      }
    })
  });
};

