  let unleash: UnleashClient;

  beforeAll(async () => {
    unleash = new UnleashClient({
      url: process.env.UNLEASH_URL || 'http://localhost:4242/api/',
      appName: 'web-integration-tests',
      customHeaders: { Authorization: process.env.UNLEASH_TOKEN || 'default' },
    });
    await unleash.start();
  });

  afterAll(async () => {
    await unleash.destroy();
  });

  it('should return legacy tiers by default', () => {
    const tiers = getPricingTiers({ isEnabled: () => false });
    expect(tiers).toBe(LEGACY_TIERS);
  });

  it('should return new tiers when new-pricing is enabled', () => {
    const tiers = getPricingTiers({ isEnabled: (name) => name === 'new-pricing' });
    expect(tiers).toBe(NEW_TIERS);
  });

  it('should respect the actual Unleash state for new-pricing', () => {
    const enabled = unleash.isEnabled('new-pricing');
    const tiers = getPricingTiers(unleash);
    expect(tiers).toBe(enabled ? NEW_TIERS : LEGACY_TIERS);
  });
});

